import { useEffect, useRef } from "react";
import gsap from "gsap";
import { ArrowDown, ArrowUpRight } from "lucide-react";
import heroImg from "@/assets/hero-living-room.jpg";

const line1 = ["Living,"];
const line2 = ["quietly"];
const line3 = ["automated."];

const metrics = [
  { value: "12+", label: "Years of integration" },
  { value: "480", label: "Spaces automated" },
  { value: "24/7", label: "Managed support" },
];

export function Hero() {
  const root = useRef<HTMLElement | null>(null);
  const frame = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const ctx = gsap.context(() => {
      const tl = gsap.timeline({ defaults: { ease: "expo.out" } });

      tl.from("[data-eyebrow]", { yPercent: 120, opacity: 0, duration: 1 }, 0)
        .from(
          "[data-word]",
          { yPercent: 115, duration: 1.3, stagger: 0.08 },
          0.1,
        )
        .from("[data-rule]", { scaleX: 0, duration: 1.4, transformOrigin: "left center" }, 0.5)
        .from("[data-sub]", { y: 18, opacity: 0, duration: 1 }, 0.7)
        .from("[data-cta]", { y: 18, opacity: 0, duration: 0.9, stagger: 0.08 }, 0.85)
        .from(
          "[data-frame]",
          { clipPath: "inset(100% 0% 0% 0%)", scale: 1.06, duration: 1.6 },
          0.35,
        )
        .from("[data-metric]", { y: 16, opacity: 0, duration: 0.9, stagger: 0.1 }, 1.1)
        .from("[data-cue]", { opacity: 0, duration: 0.8 }, 1.4);

      // gentle continuous float + mouse parallax on the image
      gsap.to("[data-img]", {
        yPercent: -3,
        duration: 6,
        repeat: -1,
        yoyo: true,
        ease: "sine.inOut",
      });

      const onMove = (e: PointerEvent) => {
        const el = frame.current;
        if (!el) return;
        const r = el.getBoundingClientRect();
        const dx = (e.clientX - (r.left + r.width / 2)) / r.width;
        const dy = (e.clientY - (r.top + r.height / 2)) / r.height;
        gsap.to("[data-img]", { x: dx * 18, rotate: dx * 0.4, duration: 1.2, ease: "power3.out" });
        gsap.to("[data-float]", { x: dx * -26, y: dy * -14, duration: 1.4, ease: "power3.out" });
      };
      window.addEventListener("pointermove", onMove);
      return () => window.removeEventListener("pointermove", onMove);
    }, root);

    return () => ctx.revert();
  }, []);

  return (
    <section
      id="home"
      ref={root}
      className="bg-background relative isolate flex min-h-screen flex-col overflow-hidden"
    >
      {/* hairline grid */}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0 opacity-[0.55]"
        style={{
          backgroundImage:
            "linear-gradient(to right, color-mix(in oklab, var(--border) 70%, transparent) 1px, transparent 1px)",
          backgroundSize: "calc(100% / 6) 100%",
        }}
      />

      <div className="relative mx-auto flex w-full max-w-[1280px] flex-1 flex-col px-6 pt-28 pb-8 lg:pt-32">
        <div className="grid flex-1 items-end gap-12 lg:grid-cols-12">
          {/* copy */}
          <div className="lg:col-span-7">
            <div className="overflow-hidden">
              <p
                data-eyebrow
                className="text-muted-foreground text-[12px] tracking-[0.32em] uppercase"
              >
                FusionTech Expert — Automation Studio
              </p>
            </div>

            <h1 className="font-display text-foreground mt-8 text-[clamp(2.8rem,7.2vw,6rem)] leading-[0.92] font-extrabold tracking-[-0.045em]">
              {[line1, line2, line3].map((words, i) => (
                <span key={i} className="block overflow-hidden py-[0.06em]">
                  <span
                    data-word
                    className={i === 2 ? "text-primary block" : "block"}
                  >
                    {words.join(" ")}
                  </span>
                </span>
              ))}
            </h1>

            <div data-rule className="bg-border mt-10 h-px w-full" />

            <p
              data-sub
              className="text-muted-foreground mt-8 max-w-md text-[17px] leading-relaxed"
            >
              Lighting, climate, security and sound — designed as one calm system
              for homes, villas and hospitality spaces.
            </p>

            <div className="mt-9 flex flex-wrap items-center gap-4">
              <a
                data-cta
                href="#contact"
                className="bg-foreground text-background group inline-flex items-center gap-2 rounded-full px-7 py-3.5 text-[15px] font-medium transition-transform duration-300 hover:-translate-y-0.5"
              >
                Book a consultation
                <ArrowUpRight className="size-4 transition-transform duration-300 group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
              </a>
              <a
                data-cta
                href="#solutions"
                className="story-link text-foreground text-[15px] font-medium"
              >
                Explore solutions
              </a>
            </div>
          </div>

          {/* image */}
          <div className="lg:col-span-5">
            <div
              ref={frame}
              data-frame
              className="relative aspect-[4/5] w-full overflow-hidden rounded-[2px] lg:aspect-[4/5]"
              style={{ clipPath: "inset(0% 0% 0% 0%)" }}
            >
              <img
                data-img
                src={heroImg}
                alt="Minimal living room with integrated smart lighting and motorised shades"
                className="absolute inset-[-4%] size-[108%] object-cover"
                loading="eager"
              />
              <div
                data-float
                className="border-border/70 bg-background/90 absolute bottom-5 left-5 rounded-full border px-4 py-2 backdrop-blur-md"
              >
                <span className="text-foreground flex items-center gap-2 text-[12px] tracking-[0.14em] uppercase">
                  <span className="bg-primary size-1.5 animate-pulse rounded-full" />
                  Living room · calm scene
                </span>
              </div>
            </div>
          </div>
        </div>

        {/* footer row */}
        <div className="border-border mt-10 flex flex-wrap items-end justify-between gap-8 border-t pt-7">
          <div className="flex flex-wrap gap-10">
            {metrics.map((m) => (
              <div key={m.label} data-metric>
                <p className="font-display text-foreground text-2xl font-bold tracking-tight">
                  {m.value}
                </p>
                <p className="text-muted-foreground mt-1 text-[12px] tracking-[0.16em] uppercase">
                  {m.label}
                </p>
              </div>
            ))}
          </div>
          <a
            data-cue
            href="#about"
            className="text-muted-foreground hover:text-foreground flex items-center gap-2 text-[12px] tracking-[0.24em] uppercase transition-colors"
          >
            Scroll
            <ArrowDown className="size-3.5 animate-bounce" />
          </a>
        </div>
      </div>
    </section>
  );
}
